  var total = 0;

  var create = [];
  for (var [key, e] of Object.entries(src.entries)) {
    var e2 = dst.entries[key];
    if (!e2 || e['timestamp'].getTime() != e2['timestamp'].getTime()) {
      create.push(key);
      total++;
    }
  }

  var remove = [];
  for (var key of Object.keys(dst.entries)) {
    if (!src.entries[key]) {
      remove.push(key);
      total++;
    }
