  var store = transaction.objectStore(IDBFS.DB_STORE_NAME);

  function done(err) {
    if (err && !errored) {
      errored = true;
      return callback(err);
    }
  };

  // transaction may abort if (for example) there is a QuotaExceededError
  transaction.onerror = transaction.onabort = (e) => {
    done(e.target.error);
    e.preventDefault();
